    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    # Color the one-cell interior rim 2, leaving the input frame intact.
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            if r in (r0 + 1, r1 - 1) or c in (c0 + 1, c1 - 1):
                out[r][c] = 2
    # The next inset outline remains 5; color its inside region 2.
    for r in range(r0 + 2, r1 - 1):
        for c in range(c0 + 2, c1 - 1):
            if r in (r0 + 2, r1 - 2) or c in (c0 + 2, c1 - 2):
                out[r][c] = 5
            else:
                out[r][c] = 2
    return out
